// Obtener payload real del webhook
const payload = items[0].json.body;

// Validación defensiva
if (!payload || !payload.paymentId || !payload.amount) {
  throw new Error(
    'Invalid payload: paymentId or amount missing'
  );
}

// Normalizar datos
return [{
  json: {
    paymentId: payload.paymentId,
    amount: payload.amount,
    currency: payload.currency ?? 'USD',
    status: payload.type ?? 'succeeded',
    metadata: payload.metadata ?? {},
    timestamp: new Date().toISOString()
  }
}];

// 1. Importar el módulo (esto funcionará tras el paso 1)
const crypto = require('crypto');

// 2. Obtener lista de partners
const partners = [
  {
    id: 'partner_1',
    name: 'Tours Paradise',
    webhookUrl: 'http://localhost:5678/webhook/partner-webhook',
    hmacSecret: 'secret_123'
  }
];

// 3. El nodo Function recibe los datos en 'items'
const inputData = items[0].json;

const event = {
  eventType: 'payment.succeeded',
  timestamp: new Date().toISOString(),
  data: inputData
};

const outputs = [];

for (const partner of partners) {
  // Generar firma HMAC SHA256
  const signature = crypto
    .createHmac('sha256', partner.hmacSecret)
    .update(JSON.stringify(event))
    .digest('hex');

  outputs.push({
    json: {
      partnerUrl: partner.webhookUrl,
      signature: signature,
      event: event
    }
  });
}

return outputs;

