// 1. Acceder a los datos de normalización de pago
const paymentData = $( 'Validate & Normalize1' ).first().json;

// 2. Acceder a la respuesta del servidor de activación
const activationData = $( 'Activate Reservation1' ).first().json;

// Validaciones de seguridad
const email = paymentData.metadata?.userEmail;
if (!email) {
  throw new Error('Email del usuario no encontrado en los datos de pago');
}

// Procesar datos para el email
const amount = (paymentData.amount / 100).toFixed(2);
const currency = paymentData.currency || 'USD';
const reservationId = paymentData.metadata?.reservationId;

// Subject
const subject = `✅ Confirmación: Reserva ${reservationId} Activada – UNIFIT`;

// Cuerpo del email combinando ambas fuentes
const body = `
Hola,

Tenemos buenas noticias: tu pago ha sido procesado y tu reserva ya está activa.

📌 Detalles del Pago (de Validate & Normalize):
- ID de Transacción: ${paymentData.paymentId}
- Monto: ${amount} ${currency}
- Estado del Pago: ${paymentData.status}

🚀 Detalles de la Activación (de Activate Reservation):
- Reserva ID: ${reservationId}
- Mensaje del Sistema: ${activationData.message || 'Activación completada con éxito'}
- Fecha de Activación: ${new Date().toLocaleString()}

Tu acceso a UNIFIT ya está habilitado. ¡Disfrútalo!

Gracias por confiar en nosotros.
Equipo UNIFIT 💪
`.trim();

return [
  {
    json: {
      to: email,
      subject,
      message: body // Usamos "message" para que coincida con lo que espera tu nodo de Gmail
    }
  }
];
